from wardline.supplies.store import Cabinet
from wardline.supplies.models import Supply
def mk(n, cat='x'):
    s = Cabinet()
    for k in range(n):
        s.add(Supply(id='k%02d' % k, name='N%02d' % k, ward=cat, stock=(k * 5) % 7, price=1.0 + k))
    return s
from wardline.supplies.errors import Invalid
s = mk(2)
try:
    s.add(Supply(id='k01', name='z', ward='c'))
except Invalid as e:
    print(e, s.count(), s.get('k01').name)

